        if row[0] != 0 and all(v == row[0] for v in row):
            line = ('row', r)
            break
    if line is None:
        for c in range(w):
            col = [grid[r][c] for r in range(h)]
            if col[0] != 0 and all(v == col[0] for v in col):
                line = ('col', c)
                break
    if line is None:
        return [row[:] for row in grid]
    out = [[0] * w for _ in range(h)]
    axis, idx = line
