        out[idx] = grid[idx][:]
        for c in range(w):
            vals = [grid[r][c] for r in range(h) if r != idx and grid[r][c] != 0]
            # Pack toward boundary, retaining input order.
            if idx == 0:
                for i, v in enumerate(vals): out[1+i][c] = v
            else:
                for i, v in enumerate(vals): out[h-len(vals)+i][c] = v
    else:
        for r in range(h):
            out[r][idx] = grid[r][idx]
            vals = [grid[r][c] for c in range(w) if c != idx and grid[r][c] != 0]
            if idx == 0:
                for i, v in enumerate(vals): out[r][1+i] = v
            else:
