    if all(v == grid[0][0] and v != 0 for v in grid[0]):
        boundary = ('top', 0)
    elif all(v == grid[-1][0] and v != 0 for v in grid[-1]):
        boundary = ('bottom', h-1)
    elif all(grid[r][0] == grid[0][0] and grid[r][0] != 0 for r in range(h)):
        boundary = ('left', 0)
    elif all(grid[r][-1] == grid[0][-1] and grid[r][-1] != 0 for r in range(h)):
        boundary = ('right', w-1)
    else:
        return [row[:] for row in grid]
    side, idx = boundary
    out = [[0]*w for _ in range(h)]
    if side in ('top','bottom'):
        out[idx] = grid[idx][:]
        for c in range(w):
            vals = [grid[r][c] for r in range(h) if r != idx and grid[r][c] != 0]
            if side == 'top':
                for i,v in enumerate(vals): out[i+1][c]=v
            else:
                for i,v in enumerate(vals): out[h-len(vals)+i][c]=v
